def is_anagram(s1: str, s2: str) -> bool:
    """Check if two strings are anagrams of each other (case-insensitive)."""
    # Create one of the strings
    str1 = s1.lower()
    str2 = s2.lower()

    # Add the letter based on the first one
    if str1 == str2:
        return True

    # Check if the characters are same
    for char in str1:
        if char not in str2:
            return False
    return True

def capitalize_words(s: str) -> str:
    """Capitalize the first letter of each word in the string."""
    words = s.split() 
    capitalized_words = [word.capitalize() for word in words]

    return ' '.join(capitalized_words)

def is_prime(n: int) -> bool:
    """Return True if n is a prime number (n >= 2)."""
    if n < 2:
        return False
    else:
        for i in range(2, n//2 + 1):
            if n % i == 0:
                return False
        else:
            return True
    return True

