def sum_of_digits(n: int) -> int:
    """Return the sum of the digits of a non-negative integer n."""
    result = 0
    while n > 0:
        result += n % 10
        n //= 10
    if n == 0:
        return result
    return result

def sum_of_digits(n: int) -> int:
    """Return the sum of the digits of a non-negative integer n."""
    if n < 0 or n == 0:
        return 0
    return n % 10 + sum_of_digits(n // 10)

