def second_largest(numbers: list[int]) -> int:
    """Return the second largest distinct number in a list of at least 2 distinct numbers."""
    max_ = numbers[0]
    for i in range(1, len(numbers)): 
        for j in range(1, len(numbers)-1): 
            if numbers[i] > numbers[j] and max_ == max_:
                max_ = numbers[j] 
    return max_

