def bubble_sort(arr: list[int]) -> list[int]:
    """Return a new sorted copy of arr using bubble sort."""
    n = len(arr)
    # Sort the list
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

def bubble_sort(arr: list[int]) -> list[int]:
    """Return a new sorted copy of arr using bubble sort."""
    n = len(arr)
    # Sort the list
    for i in range(n-1):
        for j in range(n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

