def caesar_cipher(text: str, shift: int) -> str:
    """Shift alphabetic characters in text by shift positions (preserving case)."""
    cipher_text = ""
    for char in text:
        if char.isalpha():
            if char.isupper():
                cipher_text += chr((ord(char) + shift - 65) % 26 + 65)
            else:
                cipher_text += chr((ord(char) + shift - 97) % 26 + 97)
        else:
            cipher_text += char
    return cipher_text

