def caesar_cipher(text: str, shift: int) -> str:
    """Shift alphabetic characters in text by shift positions (preserving case)."""
    cipher = ""
    for char in text:
        if char.isalpha():
            if char.isupper():
                cipher += chr((ord(char) + shift - 65) % 26 + 65)
            else:
                cipher += chr((ord(char) + shift - 97) % 26 + 97)
        else:
            cipher += char
    return cipher

