def is_anagram(s1: str, s2: str) -> bool:
    """Check if two strings are anagrams of each other (case-insensitive)."""
    # Create one of the strings
    str1 = s1.lower()
    str2 = s2.lower()

    # Add the letter based on the first one
    if str1 == str2:
        return True

    # Check if the characters are same
    for char in str1:
        if char not in str2:
            return False
    return True

