def frequency_map(items: list) -> dict:
    """Return a dictionary mapping each item to its frequency count."""
    # Create a dictionary to store the result
    result = {}
    for item in items:
        # If the item is already present in the dictionary, add it
        if item in result.keys():
            result[item] += 1
        else:
            result[item] = 1
    return result

